    internal static bool TryDecodeRanges(string normalizedName, out int[] ranges)
    {
        if (!TryResolveEncodedRanges(normalizedName, out var encoded))
        {
            ranges = [];
            return false;
        }

        var bytes = Convert.FromBase64String(encoded);
        var values = new List<int>();
        var previous = 0;
        for (var index = 0; index < bytes.Length;)
        {
            var delta = 0;
            var shift = 0;
            byte current;
            do
            {
                current = bytes[index++];
                delta |= (current & 0x7F) << shift;
                shift += 7;
            }
            while ((current & 0x80) != 0);

            previous += delta;
            values.Add(previous);
        }

        ranges = values.ToArray();
        return true;
    }
